parameters.jsCode:
// ════════════════════════════════════════════════════════
// Save to DB + Embed Facts v2
// ════════════════════════════════════════════════════════
// 1. Update User.persona (JSONB)
// 2. Mark raw_messages as processed
// 3. Upsert key_facts → memory_facts (deduped)
// 4. NEW: Embed each new fact → memory_embeddings (vector)
//    ทำให้ facts ถูกค้นด้วย vector search ใน Memory Injector ได้
// ════════════════════════════════════════════════════════
const item = $input.first().json;
const userId = item.userId;
const updatedPersona = item.updatedPersona;
const keyFacts = item.keyFacts || [];
const emotionalPatterns = item.emotionalPatterns || [];

const dbUrl = process.env.DATABASE_URL || '';
if (!dbUrl) {
  console.error('[WF5-A Save] DATABASE_URL not set');
  return { json: { ...item, saved: false, reason: 'no_db_url' } };
}

// OpenRouter key for embedding new facts
const embedKey = updatedPersona?.tokens?.openrouter_access_token || process.env.OPENROUTER_API_KEY || '';

const { Pool } = require('pg');
const pool = new Pool({ connectionString: dbUrl });

try {
  // ── 1. Update User.persona ─────────────────────────────────
  await pool.query(
    'UPDATE "User" SET persona = $1::jsonb, updated_at = NOW() WHERE id = $2',
    [JSON.stringify(updatedPersona), userId]
  );

  // ── 2. Mark raw_messages as processed ─────────────────────
  await pool.query(
    `UPDATE user_data_schema.raw_messages
     SET processed_for_memory = true
     WHERE session_id IN (
       SELECT id FROM user_data_schema.chat_sessions WHERE user_id = $1
     )
     AND processed_for_memory = false
     AND created_at > NOW() - INTERVAL '7 hours'`,
    [userId]
  );

  // ── 3. Upsert key_facts ────────────────────────────────────
  const newFacts = [];
  for (const fact of keyFacts) {
    if (!fact || fact.length < 5) continue;
    try {
      const res = await pool.query(
        `INSERT INTO user_data_schema.memory_facts (user_id, fact, source, created_at)
         VALUES ($1, $2, 'wf5a', NOW())
         ON CONFLICT (user_id, fact) DO NOTHING
         RETURNING fact`,
        [userId, fact]
      );
      if (res.rows.length > 0) newFacts.push(fact); // only newly inserted
    } catch (e) {
      console.log('[WF5-A] memory_facts skip:', e.message);
    }
  }

  // ── 4. Embed new facts → memory_embeddings ────────────────
  let embeddedCount = 0;
  if (newFacts.length > 0 && embedKey) {
    for (const fact of newFacts) {
      try {
        const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${embedKey}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            model: 'openai/text-embedding-3-small',
            input: fact
          })
        });

        if (!embedRes.ok) {
          console.warn(`[WF5-A] Embed fact failed: ${embedRes.status}`);
          continue;
        }

        const embedData = await embedRes.json();
        const embedding = embedData.data?.[0]?.embedding;
        if (!embedding) continue;

        const vectorStr = `[${embedding.join(',')}]`;
        await pool.query(
          `INSERT INTO user_data_schema.memory_embeddings
             (user_id, content, embedding, metadata, created_at)
           VALUES ($1, $2, $3::vector, $4::jsonb, NOW())
           ON CONFLICT DO NOTHING`,
          [
            userId,
            fact,
            vectorStr,
            JSON.stringify({ type: 'key_fact', source: 'wf5a', classification: 'factual_memory' })
          ]
        );
        embeddedCount++;
      } catch (e) {
        console.log('[WF5-A] embed fact skip:', e.message);
      }
    }
  }

  // ── 5. Save emotional_patterns as interaction_memories ─────
  for (const pattern of emotionalPatterns.slice(0, 3)) {
    if (!pattern || pattern.length < 5) continue;
    try {
      await pool.query(
        `INSERT INTO user_data_schema.interaction_memories
           (user_id, text, classification, created_at)
         VALUES ($1, $2, 'emotional_pattern', NOW())
         ON CONFLICT DO NOTHING`,
        [userId, pattern]
      );
    } catch (e) {
      console.log('[WF5-A] emotional_pattern skip:', e.message);
    }
  }

  await pool.end();

  console.log(`[WF5-A Save] ✅ userId=${userId.slice(0,8)}... | facts_new=${newFacts.length} | embedded=${embeddedCount} | patterns=${emotionalPatterns.length}`);
  return {
    json: {
      ...item,
      saved: true,
      factsNew: newFacts.length,
      factsEmbedded: embeddedCount,
      patternsSaved: emotionalPatterns.length,
      personaKeys: Object.keys(updatedPersona).length
    }
  };

} catch (err) {
  console.error('[WF5-A Save] DB error:', err.message);
  try { await pool.end(); } catch(_) {}
  return { json: { ...item, saved: false, reason: err.message } };
}

const item = $input.first().json;
console.log('[WF5-A Skip]', item.userId?.substring(0,8), '| reason:', item.skipReason || 'parse_error_or_no_data');
return { json: { status: 'skipped', userId: item.userId, reason: item.skipReason } };

// Get Active Users v3 — Code node (replaces postgres node with hardcoded credential)
// หา users ที่มี unprocessed messages ในช่วง 7 ชั่วโมงที่ผ่านมา (อย่างน้อย 3 messages)
const dbUrl = process.env.DATABASE_URL || '';
if (!dbUrl) {
  console.error('[WF5-A GetUsers] DATABASE_URL not set');
  return [];
}

try {
  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const result = await pool.query(`
    SELECT DISTINCT s.user_id
    FROM user_data_schema.chat_sessions s
    JOIN user_data_schema.raw_messages m ON m.session_id = s.id
    WHERE m.created_at > NOW() - INTERVAL '7 hours'
      AND m.processed_for_memory = false
    GROUP BY s.user_id
    HAVING COUNT(m.id) >= 3
  `);
  await pool.end();
  console.log(`[WF5-A GetUsers] Found ${result.rows.length} active users`);
  return result.rows.map(row => ({ json: row }));
} catch (err) {
  console.error('[WF5-A GetUsers] DB error:', err.message);
  return [];
}

// Load Unprocessed Messages v3 — Code node (replaces postgres node with hardcoded credential)
const userId = $('Split Users').item.json.user_id;
const dbUrl = process.env.DATABASE_URL || '';
if (!dbUrl) {
  console.error('[WF5-A LoadMsgs] DATABASE_URL not set');
  return [{ json: { _error: 'no_db_url', user_id: userId, rows: [] } }];
}

try {
  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const result = await pool.query(
    `SELECT m.role, m.content, m.created_at, m.category
     FROM user_data_schema.raw_messages m
     JOIN user_data_schema.chat_sessions s ON m.session_id = s.id
     WHERE s.user_id = $1
       AND m.created_at > NOW() - INTERVAL '7 hours'
       AND m.processed_for_memory = false
     ORDER BY m.created_at ASC
     LIMIT 100`,
    [userId]
  );
  await pool.end();
  console.log(`[WF5-A LoadMsgs] userId: ${userId.substring(0,8)}... | messages: ${result.rows.length}`);
  // ส่ง rows ทั้งหมดเป็น array ของ items เพื่อให้ Merge for Analysis รับได้
  return result.rows.map(row => ({ json: { ...row, _userId: userId } }));
} catch (err) {
  console.error('[WF5-A LoadMsgs] DB error:', err.message);
  return [{ json: { _error: err.message, user_id: userId, rows: [] } }];
}

// Load Current Persona v3 — Code node (replaces postgres node with hardcoded credential)
const userId = $('Split Users').item.json.user_id;
const dbUrl = process.env.DATABASE_URL || '';
if (!dbUrl) {
  console.error('[WF5-A LoadPersona] DATABASE_URL not set');
  return [{ json: { _error: 'no_db_url', user_id: userId } }];
}

try {
  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const result = await pool.query(
    `SELECT id, name, email, language_preference, timezone,
            persona, "subscriptionTier"
     FROM "User"
     WHERE id = $1
     LIMIT 1`,
    [userId]
  );
  await pool.end();
  const row = result.rows[0] || {};
  console.log(`[WF5-A LoadPersona] userId: ${userId.substring(0,8)}... | name: ${row.name || '(none)'}`);
  return [{ json: row }];
} catch (err) {
  console.error('[WF5-A LoadPersona] DB error:', err.message);
  return [{ json: { _error: err.message, user_id: userId } }];
}

const msgs = $('Load Unprocessed Messages').all().map(i => i.json);
const personaRow = $('Load Current Persona').first()?.json || {};
const userId = $('Split Users').item.json.user_id;

let currentPersona = {};
try {
  const raw = personaRow.persona;
  currentPersona = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
} catch(e) { currentPersona = {}; }

const conversation = msgs
  .filter(m => m.role && m.content) // กรอง error rows ออก
  .map(m => `[${m.role?.toUpperCase() || 'USER'}]: ${m.content}`)
  .join('\n')
  .slice(0, 3000);

const userMeta = {
  name: personaRow.name || 'User',
  language: personaRow.language_preference || 'th',
  timezone: personaRow.timezone || 'Asia/Bangkok'
};

console.log(`[WF5-A Merge] userId: ${userId.substring(0,8)}... | messages: ${msgs.length} | personaKeys: ${Object.keys(currentPersona).length}`);

return {
  json: { userId, userMeta, currentPersona, conversation, messageCount: msgs.length }
};

const item = $input.first().json;
const rawOutput = item.text || item.output || item.response || '{}';
const userId = $('Merge for Analysis').item.json.userId;
const currentPersona = $('Merge for Analysis').item.json.currentPersona;
const userMeta = $('Merge for Analysis').item.json.userMeta;

let memoryUpdate = {};
try {
  const cleaned = rawOutput.replace(/```json|```/g, '').trim();
  memoryUpdate = JSON.parse(cleaned);
} catch(e) {
  console.error('[WF5-A Parse] JSON parse error:', e.message, '| raw:', rawOutput.slice(0, 200));
  return {
    json: {
      userId, updatedPersona: currentPersona,
      keyFacts: [], emotionalPatterns: [],
      languageDetected: userMeta.language,
      skip: true, skipReason: 'json_parse_error'
    }
  };
}

const pu = memoryUpdate.persona_updates || {};

// Merge arrays deduped
const mergedInterests = [...new Set([
  ...(currentPersona.interests || []),
  ...(pu.interests || [])
])];

const mergedPreferences = {
  ...(currentPersona.preferences || {}),
  ...(pu.preferences || {})
};

const mergedPhysicalStats = {
  ...(currentPersona.physical_stats || {}),
  ...(Object.keys(pu.physical_stats || {}).some(k => pu.physical_stats[k] != null)
    ? pu.physical_stats : {})
};

// NEW: merge relationship_facts + goals_and_aspirations
const mergedRelationships = [...new Set([
  ...(currentPersona.relationship_facts || []),
  ...(memoryUpdate.relationship_facts || [])
])];

const mergedGoals = [...new Set([
  ...(currentPersona.goals_and_aspirations || []),
  ...(memoryUpdate.goals_and_aspirations || [])
])];

const updatedPersona = {
  ...currentPersona,
  interests: mergedInterests,
  preferences: mergedPreferences,
  physical_stats: mergedPhysicalStats,
  personality_notes: pu.personality_notes || currentPersona.personality_notes || null,
  language_preference: memoryUpdate.language_detected || currentPersona.language_preference || userMeta.language,
  relationship_facts: mergedRelationships,
  goals_and_aspirations: mergedGoals,
  _last_memory_update: new Date().toISOString()
};

const keyFacts = memoryUpdate.key_facts || [];
const emotionalPatterns = memoryUpdate.emotional_patterns || [];

console.log(`[WF5-A Parse] userId=${userId.slice(0,8)}... | facts=${keyFacts.length} | emotions=${emotionalPatterns.length} | goals=${mergedGoals.length} | relationships=${mergedRelationships.length}`);

return {
  json: {
    userId, updatedPersona,
    keyFacts, emotionalPatterns,
    relationshipFacts: memoryUpdate.relationship_facts || [],
    goalsAndAspirations: memoryUpdate.goals_and_aspirations || [],
    languageDetected: memoryUpdate.language_detected || userMeta.language,
    skip: false
  }
};
